_BY_ID: dict[str, PdmOperationSpec] = {op.id: op for op in OPERATIONS}


def find_operation(op_id: str) -> PdmOperationSpec | None:
    """Look up one catalogued operation by its stable id, or None when unknown."""
    return _BY_ID.get(op_id)
